const HAWADIT = [
["جُحا وابنه كانوا ماشيين في السوق ومعاهم حمار. جُحا رِكب وابنه ماشي، فالناس قالت شوف الراجل القاسي راكب وسايب العيّل يتعب. نِزل جُحا وركّب ابنه، قالوا شوف الولد قليل الأدب راكب وأبوه العجوز ماشي. ركبوا الاتنين، قالوا يا حرام على الحمار الغلبان. نزلوا الاتنين ومشيوا جنبه، قالوا شوف الأغبيا معاهم حمار وماشيين على رِجليهم. ساعتها جُحا بَصّ لابنه وقال: شُفت؟ رِضا الناس غاية لا تُدرك.","حدوتة جحا والحمار"],
["جُحا باع بيته لواحد وقاله شَرط واحد بس، المسمار اللّي في الحيطة ده يفضل بتاعي. الراجل وافق وقال ده مسمار يعني. تاني يوم جُحا خبط على الباب وقال جاي أطّمن على مسماري. وبعده بيوم جه علّق عليه جلّابيّة، وبعدها علّق عليه قفّة، ولمّا الراجل زِهق، جُحا جاب حمار ميّت وعلّقه في المسمار. الراجل ساب البيت وخرج، ومن ساعتها اللّي يسيب حُجّة صغيّرة يرجع بيها يقولوا عليها مسمار جُحا.","حدوتة مسمار جحا"],
["جُحا استلف قِدرة من جاره، ورجّعهاله ومعاها قِدرة صغيّرة. الجار استغرب، فقاله جُحا مبروك يا جاري، القِدرة بتاعتك ولدت. الجار فِرح وأخد الاتنين. بعد شويّة جُحا استلف القِدرة تاني وما رجّعهاش، والجار راح يسأل عليها، قاله جُحا البقيّة في حياتك، القِدرة ماتت. الجار زَعّق وقال هي القِدرة بتموت؟ ردّ جُحا وقال: صدّقت إنّها بتولد، ومش مصدّق إنّها تموت؟","حدوتة قدرة جحا"],
["جُحا راح فرح بهدومه القديمة، محدّش عبّره ولا قعّده في مكان كويّس. رجع البيت لِبس أحسن جُبّة عنده ورجع تاني، الناس قامتله وقعّدوه في الصدارة وحطّوا قدّامه الأكل. جُحا بدأ يمسك الأكل ويحُطّه في كُمّه ويقول كُل يا كُمّي، كُل يا كُمّي. الناس سألوه بتعمل إيه يا جُحا؟ قال: ما هو العزومة دي للجُبّة مش ليّا، يبقى هي اللّي تاكل.","حدوتة كل يا كمي"],
["مرّة واحد فقير قعد جنب مطعم كبير، وطلّع رغيف عيش ناشف وقعد ياكله على ريحة الشَوي. صاحب المطعم خرج ومِسكه وقاله ادفع تمن الريحة. راحوا لجُحا يحكم بينهم. جُحا طلّع كيس فيه فلوس ورنّه جنب وِدن صاحب المطعم، وقاله خلاص، خدت حقّك. الراجل قال إزاي؟ قاله جُحا: هو شمّ ريحة أكلك، وانت سمعت صوت فلوسه، تبقوا خالصين.","حدوتة جحا وريحة الشوي"],
["جُحا كان راجع من السوق ومعاه عَشر حمير. رِكب واحد منهم وعدّهم لقاهم تِسعة. نِزل وعدّهم تاني لقاهم عَشرة. رِكب وعدّهم لقاهم تِسعة. فضل يطلع وينزل لحدّ ما تِعب، وفي الآخر قال: خلاص، أمشي على رِجلي وأكسب حمار أحسن ما أركب وأخسر واحد.","حدوتة جحا والحمير العشرة"],
["طلبوا من جُحا يخطب في الناس، طِلع على المِنبر وسألهم: تعرفوا أنا هقول إيه؟ قالوا لأ. قال طب إزاي أكلّم ناس ما يعرفوش أنا هقول إيه؟ ونِزل. تاني جُمعة سألهم نفس السؤال، قالوا آه عارفين. قال طالما عارفين يبقى مفيش داعي أتكلّم، ونِزل. التالتة اتّفقوا يقسموا نفسهم، نُصّ يقول عارفين ونُصّ يقول مش عارفين. جُحا قال حِلو أوي، اللّي يعرف يقول للّي ما يعرفش. ونِزل.","حدوتة خطبة جحا"],
["جار جُحا جه يستلف منه الحَبل. جُحا قاله آسف، الحَبل مش فاضي، أنا بنشُر عليه دقيق. الجار استغرب وقال حدّ ينشُر دقيق على حَبل؟ قاله جُحا: لمّا الواحد ما يكونش عايز يسلّف حاجة، أيّ حُجّة بتنفع.","حدوتة حبل جحا"],
["جُحا كان بيدوّر على حاجة في الشارع تحت عمود النور. واحد سأله بتدوّر على إيه يا جُحا؟ قال على خاتمي. قعدوا يدوّروا معاه ساعة ومش لاقيين. سألوه هو وقع منك فين بالظبط؟ قال جوّه البيت. قالوا طب ليه بتدوّر هنا؟ قال: ما هو هنا فيه نور، وجوّه البيت ضَلمة.","حدوتة خاتم جحا"],
["جُحا كان قاضي البلد، جاله راجل اشتكى من جاره، جُحا سِمعه وقاله عندك حقّ. جه الجار وحكى حكايته، جُحا قاله وانت كمان عندك حقّ. مرات جُحا كانت بتسمع، قالتله إزاي الاتنين عندهم حقّ؟ لازم واحد فيهم غلطان. جُحا بصّلها وقال: وانتي كمان عندك حقّ.","حدوتة جحا القاضي"],
["مرّة جُحا وقف في وسط السوق وقال يا ناس، اللّي يجيب لي حماري اللّي ضاع هدّيله الحمار هديّة. الناس استغربت وقالوا هتدّي الحمار للّي يلاقيه؟ طب بتدوّر عليه ليه؟ قال: انتو ما تعرفوش حلاوة إن الواحد يلاقي حاجة ضاعت منه.","حدوتة حمار جحا الضايع"],
["جُحا طبخ أكلة حِلوة وعزم صحابه، وقبل ما يقعدوا قالهم مين فيكم عنده سِنان؟ كُلّ واحد قال أنا. قالهم طب حدّ عنده سِنان وعنده كمان صَبر يستنّى الأكل يبرد؟ محدّش ردّ. فجُحا قعد ياكل لوَحده وقال: الأكل للّي عنده الاتنين.","حدوتة عزومة جحا"],
["جُحا كان بيعدّي النهر بالمركب مع واحد نَحوي متكبّر. النَحوي سأله: يا جُحا انت قريت النَحو؟ قال لأ. قاله: يبقى ضاع نُصّ عُمرك. بعد شويّة الموج علي والمركب بدأت تغرق، جُحا بَصّ للنَحوي وقاله: انت اتعلّمت العوم؟ قال لأ. قاله جُحا: يبقى ضاع عُمرك كُلّه.","حدوتة جحا والنحوي"],
["جُحا ضاع منه حماره، فقعد يحمد ربّنا بصوت عالي. الناس استغربت وقالوا بتحمد ربّنا على إيه وحمارك ضاع؟ قال: بحمده إنّي ما كُنتش راكب عليه، وإلّا كُنت ضُعت معاه.","حدوتة حمد جحا"],
["واحد قال لجُحا: شُفت الصينيّة اللّي فيها الأكل اللّي عدّت من هنا؟ قال جُحا: وأنا مالي. قاله: ده كانت داخلة بيتك. قال جُحا: وانت مالك. وكمّل مشيه وهو مبسوط، لأن عنده قاعدة: الخبر اللّي ما يخصّكش ما تسألش عليه، واللّي يخصّك هيوصلك.","حدوتة صينية جحا"],
["جُحا كان راكب حماره بالمقلوب، وِشّه ناحية ديل الحمار. الناس ضِحكت وسألته ليه راكب كده يا جُحا؟ قال: أنا مش راكب بالمقلوب، الحمار هو اللّي ماشي بالمقلوب. ولمّا زنّوا عليه قال: بصراحة لو ركبت عِدل هدّيكم ضَهري، ولو مشيت قدّامكم هتبقوا ورايا، فالأحسن أفضل باصص لكم وأنا ماشي.","حدوتة جحا والحمار المقلوب"]
];
